        if len(heap) < k:
            heapq.heappush(heap, val)
        elif val > heap[0]:
            heapq.heappushpop(heap, val)

    # Extract and convert back if needed
    result = [heapq.heappop(heap)[1] for _ in range(len(heap))]
    if use_neg:
        result = [-x for x in result]
    # Sort by (frequency, value) ascending
    result.sort(key=lambda x: (freq[x], x))
    return result

